HELP_KEYS = ('qb_url','qb_username','qb_password','qb_save_path','check_minutes','max_managed_torrents','max_disk_usage_percent','min_size_gb','max_size_gb','startup','close_to_tray','desktopicon')
def extend(text):
    for code, row in ROWS.items():
        values = row.split('|')
        if len(values) != len(KEYS) or len(HELP[code]) != len(HELP_KEYS):
            raise ValueError(code)
        text[code].update(zip(KEYS,values))
        text[code].update(('help_'+k,v) for k,v in zip(HELP_KEYS,HELP[code]))

